286	package hotel.reservations;
287	
288	import java.math.BigDecimal;
289	import java.sql.Connection;
290	import java.sql.Date;
291	import java.sql.PreparedStatement;
292	import java.sql.ResultSet;
293	import java.sql.SQLException;
294	import java.time.LocalDate;
295	import java.util.ArrayList;
296	import java.util.List;
297	import java.util.Optional;
298	import javax.sql.DataSource;
299	
300	/** Keeps the reservations in the database. */
301	public final class ReservationStore {
302	
303	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
304	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
305	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
306	    private static final String EXCLUSION_VIOLATION = "23P01";
307	
308	    private final DataSource dataSource;
309	
310	    public ReservationStore(DataSource dataSource) {
311	        this.dataSource = dataSource;
312	    }
313	
314	    /** Saves a new reservation; the database numbers it. */
315	    Reservation add(NewReservation request, Price price) {
316	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
317	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
318	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
319	        try (Connection connection = dataSource.getConnection();
320	                PreparedStatement statement = connection.prepareStatement(insert)) {
321	            statement.setInt(1, request.roomNumber());
322	            statement.setString(2, request.guest().name());
323	            statement.setString(3, request.guest().email());
324	            statement.setString(4, request.guest().cpf());
325	            statement.setDate(5, Date.valueOf(request.checkIn()));
326	            statement.setDate(6, Date.valueOf(request.checkOut()));
327	            statement.setInt(7, request.guests());
328	            statement.setString(8, request.ratePlan().name());
329	            statement.setInt(9, price.nights());
330	            statement.setBigDecimal(10, price.subtotal());
331	            statement.setBigDecimal(11, price.discount());
332	            statement.setBigDecimal(12, price.total());
333	            statement.setString(13, ReservationStatus.PENDING.name());
334	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
335	            try (ResultSet generated = statement.executeQuery()) {
336	                generated.next();
337	                return new Reservation(generated.getLong("id"), request, price);
338	            }
339	        } catch (SQLException failure) {
340	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
341	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
342	                        "room " + request.roomNumber() + " is taken on some of those nights");
343	            }
344	            throw new IllegalStateException("could not save the reservation", failure);
345	        }
346	    }
347	
348	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
349	    void update(Reservation reservation) {
350	        try (Connection connection = dataSource.getConnection();
351	                PreparedStatement statement = connection.prepareStatement(
352	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
353	            statement.setString(1, reservation.status().name());
354	            statement.setBigDecimal(2, reservation.amountPaid());
355	            statement.setBigDecimal(3, reservation.refund());
356	            statement.setLong(4, reservation.id());
357	            statement.executeUpdate();
358	        } catch (SQLException failure) {
359	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
360	        }
361	    }
362	
363	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
364	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
365	        try (Connection connection = dataSource.getConnection();
366	                PreparedStatement select = connection.prepareStatement(
367	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
368	                                + "AND check_in < ? AND ? < check_out")) {
369	            select.setInt(1, roomNumber);
