363	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
364	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
365	        try (Connection connection = dataSource.getConnection();
366	                PreparedStatement select = connection.prepareStatement(
367	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
368	                                + "AND check_in < ? AND ? < check_out")) {
369	            select.setInt(1, roomNumber);
370	            select.setDate(2, Date.valueOf(checkOut));
371	            select.setDate(3, Date.valueOf(checkIn));
372	            try (ResultSet rows = select.executeQuery()) {
373	                return rows.next();
374	            }
375	        } catch (SQLException failure) {
376	            throw new IllegalStateException("could not check room " + roomNumber, failure);
377	        }
378	    }
